/**
 * AgroScan AI - Agronomic Detailed Technical Report Component.
 *
 * Provides a high-contrast, bilingual (ES/EN) phytosanitary report generated by Gemini AI,
 * detailing infection conditions, 48-hour dispersal prognosis, 20L backpack tank mixing protocol,
 * and chemical rotation & pre-harvest safety intervals.
 */

import React, { useState } from 'react';
import {
  FileText,
  CloudRain,
  AlertTriangle,
  FlaskConical,
  Calendar,
  ChevronDown,
  ChevronUp,
  Clock,
  ShieldCheck,
  Droplets,
  Sparkles,
} from 'lucide-react';
import { useLanguage } from '../context/LanguageContext';

interface AgronomicDetailedReportProps {
  diagnostic: any;
  diseaseName: string;
  cropType: string;
  className?: string;
}

export const AgronomicDetailedReport: React.FC<AgronomicDetailedReportProps> = ({
  diagnostic,
  diseaseName,
  cropType,
  className = '',
}) => {
  const { language, t } = useLanguage();
  const isEn = language === 'en';
  const [isExpanded, setIsExpanded] = useState<boolean>(true);

  const sciName = (diagnostic?.scientific_name || diagnostic?.scientificName || '').toLowerCase();
  const disLower = (diseaseName || '').toLowerCase();

  // Tailored epidemiological details based on pathogen
  const isLateBlight =
    sciName.includes('phytophthora') ||
    sciName.includes('infestans') ||
    disLower.includes('tizón tardío') ||
    disLower.includes('late blight') ||
    disLower.includes('gota');

  const isEarlyBlight =
    sciName.includes('alternaria') ||
    sciName.includes('solani') ||
    disLower.includes('tizón temprano') ||
    disLower.includes('early blight');

  const isCoffeeRust =
    sciName.includes('hemileia') ||
    sciName.includes('vastatrix') ||
    disLower.includes('roya') ||
    disLower.includes('coffee rust');

  const isCornTarSpot =
    sciName.includes('phyllachora') ||
    sciName.includes('maydis') ||
    disLower.includes('mancha de asfalto') ||
    disLower.includes('tar spot');

  return (
    <div
      className={`mt-6 rounded-3xl bg-slate-900/90 dark:bg-slate-900/95 border border-slate-700/80 shadow-xl overflow-hidden transition-all ${className}`}
    >
      {/* Header Banner with Expand/Collapse Trigger */}
      <button
        type="button"
        onClick={() => setIsExpanded(!isExpanded)}
        className="w-full p-4 sm:p-6 flex items-center justify-between text-left bg-gradient-to-r from-emerald-950/60 via-slate-900 to-teal-950/40 hover:from-emerald-900/40 transition-colors border-b border-slate-700/80"
      >
        <div className="flex items-center gap-3 sm:gap-4">
          <div className="w-12 h-12 rounded-2xl bg-emerald-600 flex items-center justify-center text-white shadow-emerald-soft shrink-0">
            <FileText className="w-6 h-6" />
          </div>
          <div>
            <div className="flex items-center gap-2.5 flex-wrap">
              <h4 className="text-lg sm:text-2xl font-black text-white tracking-tight">
                {t('technicalReportTitle')}
              </h4>
              <span className="px-3 py-1 rounded-full bg-emerald-500/20 text-emerald-300 text-xs sm:text-sm font-bold border border-emerald-500/40 flex items-center gap-1.5">
                <Sparkles className="w-3.5 h-3.5 text-emerald-400" />
                <span>{isEn ? 'Gemini 2.5 Flash • Agronomic Validation' : 'IA Gemini 2.5 Flash • Validación Agronómica'}</span>
              </span>
            </div>
            <p className="text-sm sm:text-base font-medium text-slate-300 mt-1">
              {isEn
                ? `Agronomic protocol for ${cropType}: ${diseaseName}`
                : `Protocolo agronómico para ${cropType}: ${diseaseName}`}
            </p>
          </div>
        </div>

        <div className="flex items-center gap-2 text-emerald-400 font-bold text-sm sm:text-base shrink-0 pl-3">
          <span className="hidden sm:inline">
            {isExpanded
              ? (isEn ? 'Collapse' : 'Plegar')
              : (isEn ? 'View Full Report' : 'Ver Informe Completo')}
          </span>
          {isExpanded ? <ChevronUp className="w-6 h-6" /> : <ChevronDown className="w-6 h-6" />}
        </div>
      </button>

      {/* Expanded Content Panels */}
      {isExpanded && (
        <div className="p-5 sm:p-7 space-y-6 sm:space-y-8 text-base md:text-lg leading-relaxed text-slate-100">
          {/* Bloque 1 & 2 Grid: Epidemiología + Alerta 48H */}
          <div className="grid grid-cols-1 md:grid-cols-2 gap-5">
            {/* Bloque 1: Diagnóstico y Origen Fitosanitario */}
            <div className="p-5 sm:p-6 rounded-2xl bg-slate-900/90 border border-slate-700/80 space-y-3.5 shadow-lg">
              <div className="flex items-center gap-2.5 text-emerald-400 font-extrabold text-base sm:text-lg uppercase tracking-wide">
                <CloudRain className="w-5 h-5 text-emerald-400 shrink-0" />
                <span>{t('infectionConditions')}</span>
              </div>
              <p className="text-base sm:text-lg leading-relaxed text-slate-100">
                {isLateBlight ? (
                  isEn ? (
                    <>
                      The pathogen <em>Phytophthora infestans</em> proliferates actively under relative humidity
                      exceeding <strong>90%</strong> and cool temperatures between <strong>10°C and 18°C</strong>.
                      Free water or persistent dew for more than <strong>6 to 8 hours</strong> allows biflagellated
                      zoospores to swim and penetrate rapidly through foliar stomata.
                    </>
                  ) : (
                    <>
                      El patógeno <em>Phytophthora infestans</em> prolifera activamente bajo humedad relativa
                      superior al <strong>90%</strong> y temperaturas templadas entre <strong>10°C y 18°C</strong>.
                      La presencia de agua libre o rocío persistente por más de <strong>6 a 8 horas</strong> permite
                      a las zoosporas biflageladas nadar y penetrar velozmente a través de las estomas foliares.
                    </>
                  )
                ) : isEarlyBlight ? (
                  isEn ? (
                    <>
                      <em>Alternaria solani</em> is favored by alternating high night humidity and warm day temperatures
                      (<strong>24°C - 28°C</strong>). The fungus overwinters on infected crop debris and its conidia are
                      dispersed by wind and rain splash.
                    </>
                  ) : (
                    <>
                      <em>Alternaria solani</em> se ve favorecida por fluctuaciones de alta humedad nocturna y calor diurno
                      (<strong>24°C - 28°C</strong>). El hongo sobrevive en rastrojo infectado y sus conidios son transportados
                      por el viento y salpicaduras de lluvia.
                    </>
                  )
                ) : isCoffeeRust ? (
                  isEn ? (
                    <>
                      <em>Hemileia vastatrix</em> requires free liquid water to germinate on the lower leaf surface for
                      at least <strong>4 to 6 hours</strong> with temperatures from <strong>20°C to 24°C</strong> under dense canopy shade.
                    </>
                  ) : (
                    <>
                      <em>Hemileia vastatrix</em> requiere agua líquida libre para germinar sobre el envés foliar durante
                      al menos <strong>4 a 6 horas</strong> con temperaturas de <strong>20°C a 24°C</strong> en sombra densa.
                    </>
                  )
                ) : isCornTarSpot ? (
                  isEn ? (
                    <>
                      The Tar Spot Complex (<em>Phyllachora maydis</em>) is triggered by persistent high fog,
                      relative humidity &gt; <strong>85%</strong> and prolonged cloud cover across high-altitude Andean valleys.
                    </>
                  ) : (
                    <>
                      El complejo de Mancha de Asfalto (<em>Phyllachora maydis</em>) es detonado por niebla persistente,
                      humedad relativa &gt; <strong>85%</strong> y nubosidad prolongada en valles andinos.
                    </>
                  )
                ) : isEn ? (
                  <>
                    Pathogen progression is directly coupled to microclimates with prolonged leaf wetness,
                    poor air circulation, and foliar tissue weakened by moisture or nutritional stress.
                  </>
                ) : (
                  <>
                    El desarrollo del patógeno está directamente ligado a microclimas con exceso de humedad foliar,
                    deficiente circulación de aire y tejidos foliares debilitados por estrés hídrico o nutricional.
                  </>
                )}
              </p>
              <div className="pt-3 border-t border-slate-700/80 flex items-center gap-2 text-sm sm:text-base text-slate-300 font-semibold">
                <Droplets className="w-4 h-4 text-sky-400 shrink-0" />
                <span>
                  {isEn
                    ? 'Critical Threshold: Leaf moisture film > 6 consecutive hours.'
                    : 'Umbral Crítico: Película de agua foliar > 6 horas consecutivas.'}
                </span>
              </div>
            </div>

            {/* Bloque 2: Pronóstico y Alerta de Dispersión a 48 Horas */}
            <div className="p-5 sm:p-6 rounded-2xl bg-amber-950/40 border border-amber-600/40 space-y-3.5 shadow-lg">
              <div className="flex items-center gap-2.5 text-amber-300 font-extrabold text-base sm:text-lg uppercase tracking-wide">
                <AlertTriangle className="w-5 h-5 text-amber-400 shrink-0" />
                <span>{t('dispersalPrognosis')}</span>
              </div>
              <p className="text-base sm:text-lg leading-relaxed text-amber-200">
                <strong>{isEn ? 'Immediate Phytosanitary Alert:' : 'Alerta Fitosanitaria Inmediata:'}</strong>{' '}
                {isEn
                  ? 'If systemic control or biofungicide spraying is not executed within the next 48 hours, mature sporangia will disperse via wind currents and rain splashes towards neighboring furrows and parcels.'
                  : 'Si no se ejecuta una aspersión de control sistémico o biofungicida en las próximas 48 horas, los esporangios maduros se dispersarán mediante corrientes de viento y salpicaduras de lluvia hacia los surcos y lotes vecinos.'}
              </p>
              <p className="text-sm sm:text-base leading-relaxed text-amber-300/90 font-medium">
                {isEn
                  ? 'Under high humidity conditions, a single untreated foliar lesion can produce over 300,000 spores daily, causing widespread crop blight ("burn-down") and projected yield losses between 60% and 90% in under 10 days.'
                  : 'En condiciones de alta humedad, una sola lesión no tratada puede generar más de 300,000 esporas diarias, ocasionando el tizoneo ("quemazón") generalizado del cultivo y pérdidas de rendimiento estimadas entre el 60% y el 90% en menos de 10 días.'}
              </p>
              <div className="pt-3 border-t border-amber-600/40 flex items-center gap-2 text-sm sm:text-base text-amber-300 font-bold">
                <Clock className="w-4 h-4 text-amber-400 shrink-0" />
                <span>
                  {isEn
                    ? 'Optimal Application Window: Before 48 hours elapse.'
                    : 'Ventana Óptima de Aplicación: Antes de que transcurran 48 horas.'}
                </span>
              </div>
            </div>
          </div>

          {/* Bloque 3: Protocolo Paso a Paso de Preparación en Bomba de 20 Litros */}
          <div className="p-5 sm:p-6 rounded-2xl bg-slate-900/90 border border-slate-700/80 space-y-4 shadow-lg">
            <div className="flex items-center justify-between pb-3 border-b border-slate-700/80 flex-wrap gap-2">
              <div className="flex items-center gap-2.5 text-white font-extrabold text-base sm:text-xl uppercase tracking-wide">
                <FlaskConical className="w-5 h-5 text-emerald-400 shrink-0" />
                <span>{t('mixingProtocol')}</span>
              </div>
              <span className="text-xs sm:text-sm px-3 py-1 rounded-md bg-emerald-500/20 text-emerald-300 font-bold font-mono border border-emerald-500/30">
                {isEn ? 'Official Tank Mix Sequence' : 'Orden Oficial de Mezcla'}
              </span>
            </div>

            <ol className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-5 gap-3.5 pt-1">
              <li className="p-4 rounded-xl bg-slate-800/90 border border-slate-700/90 shadow-sm flex flex-col justify-between">
                <div>
                  <span className="bg-emerald-500/20 text-emerald-300 font-bold px-3 py-1 rounded-full text-sm inline-flex items-center justify-center w-fit mb-2.5">
                    1
                  </span>
                  <p className="font-bold text-base text-white mb-1.5">
                    {isEn ? 'Initial Water Fill' : 'Carga de Agua Inicial'}
                  </p>
                  <p className="text-xs sm:text-sm text-slate-200 leading-relaxed font-normal">
                    {isEn ? (
                      <>Fill sprayer with <strong>10 liters</strong> of clean water. Verify pH between <strong>5.5 and 6.5</strong>.</>
                    ) : (
                      <>Llenar la bomba con <strong>10 litros</strong> de agua limpia. Verificar pH entre <strong>5.5 y 6.5</strong>.</>
                    )}
                  </p>
                </div>
              </li>

              <li className="p-4 rounded-xl bg-slate-800/90 border border-slate-700/90 shadow-sm flex flex-col justify-between">
                <div>
                  <span className="bg-emerald-500/20 text-emerald-300 font-bold px-3 py-1 rounded-full text-sm inline-flex items-center justify-center w-fit mb-2.5">
                    2
                  </span>
                  <p className="font-bold text-base text-white mb-1.5">
                    {isEn ? 'Bucket Pre-Mix' : 'Premezcla en Balde'}
                  </p>
                  <p className="text-xs sm:text-sm text-slate-200 leading-relaxed font-normal">
                    {isEn ? (
                      <>Dissolve in 2L bucket water: <strong>50 - 60 ml</strong> of chemical or <strong>40 g</strong> of biofungicide.</>
                    ) : (
                      <>Disolver en 2L de agua en balde: <strong>50 - 60 ml</strong> de químico o <strong>40 g</strong> de biofungicida.</>
                    )}
                  </p>
                </div>
              </li>

              <li className="p-4 rounded-xl bg-slate-800/90 border border-slate-700/90 shadow-sm flex flex-col justify-between">
                <div>
                  <span className="bg-emerald-500/20 text-emerald-300 font-bold px-3 py-1 rounded-full text-sm inline-flex items-center justify-center w-fit mb-2.5">
                    3
                  </span>
                  <p className="font-bold text-base text-white mb-1.5">
                    {isEn ? 'Adjuvant / Surfactant' : 'Coadyuvante / Adherente'}
                  </p>
                  <p className="text-xs sm:text-sm text-slate-200 leading-relaxed font-normal">
                    {isEn ? (
                      <>Add <strong>10 ml</strong> of agricultural sticker/surfactant to prevent wash-off from dew or rain.</>
                    ) : (
                      <>Agregar <strong>10 ml</strong> de adherente o surfactante agrícola para evitar el lavado por rocío o lluvias.</>
                    )}
                  </p>
                </div>
              </li>

              <li className="p-4 rounded-xl bg-slate-800/90 border border-slate-700/90 shadow-sm flex flex-col justify-between">
                <div>
                  <span className="bg-emerald-500/20 text-emerald-300 font-bold px-3 py-1 rounded-full text-sm inline-flex items-center justify-center w-fit mb-2.5">
                    4
                  </span>
                  <p className="font-bold text-base text-white mb-1.5">
                    {isEn ? 'Top-off to 20 Liters' : 'Aforo a 20 Litros'}
                  </p>
                  <p className="text-xs sm:text-sm text-slate-200 leading-relaxed font-normal">
                    {isEn ? (
                      <>Pour premix into sprayer, complete up to <strong>20 liters</strong> with water and agitate vigorously.</>
                    ) : (
                      <>Verter premezcla en la bomba, completar hasta <strong>20 litros</strong> con agua y agitar vigorosamente.</>
                    )}
                  </p>
                </div>
              </li>

              <li className="p-4 rounded-xl bg-slate-800/90 border border-slate-700/90 shadow-sm flex flex-col justify-between">
                <div>
                  <span className="bg-emerald-500/20 text-emerald-300 font-bold px-3 py-1 rounded-full text-sm inline-flex items-center justify-center w-fit mb-2.5">
                    5
                  </span>
                  <p className="font-bold text-base text-white mb-1.5">
                    {isEn ? 'Nozzle Calibration' : 'Calibración de Boquilla'}
                  </p>
                  <p className="text-xs sm:text-sm text-slate-200 leading-relaxed font-normal">
                    {isEn ? (
                      <>Use a <strong>hollow-cone nozzle</strong> (fine mist) ensuring uniform canopy coverage on both leaf surfaces.</>
                    ) : (
                      <>Usar boquilla de <strong>cono hueco</strong> (niebla fina) garantizando cubrimiento homogéneo en haz y envés foliar.</>
                    )}
                  </p>
                </div>
              </li>
            </ol>
          </div>

          {/* Bloque 4: Periodo de Carencia, Reingreso y Rotación FRAC */}
          <div className="p-5 sm:p-6 rounded-2xl bg-slate-900/90 border border-slate-700/80 flex flex-col sm:flex-row items-start sm:items-center justify-between gap-4 shadow-lg">
            <div className="space-y-1.5">
              <div className="flex items-center gap-2.5 text-white font-extrabold text-base sm:text-lg uppercase tracking-wide">
                <Calendar className="w-5 h-5 text-emerald-400 shrink-0" />
                <span>{t('rotationCalendar')}</span>
              </div>
              <p className="text-sm sm:text-base text-slate-200 max-w-2xl leading-relaxed">
                {isEn ? (
                  <>
                    • <strong>Safe field re-entry:</strong> 24 hours after application wearing full personal protective equipment (PPE).
                    <br />
                    • <strong>Pre-Harvest Interval (PHI):</strong> Respect between <strong>7 and 14 days</strong> safety period prior to harvest.
                    <br />
                    • <strong>FRAC Rotation:</strong> Do not spray the same chemical mode of action more than 2 times consecutively to prevent fungal resistance.
                  </>
                ) : (
                  <>
                    • <strong>Reingreso seguro al lote:</strong> 24 horas después de la aplicación portando EPP completo.
                    <br />
                    • <strong>Periodo de Carencia (PC):</strong> Respetar entre <strong>7 y 14 días</strong> de seguridad antes de cosechar.
                    <br />
                    • <strong>Rotación FRAC:</strong> No aplicar el mismo grupo químico más de 2 veces seguidas para prevenir resistencia fúngica.
                  </>
                )}
              </p>
            </div>

            <div className="flex items-center gap-2 shrink-0">
              <span className="px-3.5 py-2 rounded-xl bg-emerald-500/20 text-emerald-300 border border-emerald-500/40 text-sm font-bold flex items-center gap-2">
                <ShieldCheck className="w-5 h-5 text-emerald-400" />
                <span>{isEn ? 'GAP Compliant' : 'BPA Cumplido'}</span>
              </span>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default AgronomicDetailedReport;
